package com.campusmart.config;
import com.campusmart.entity.*;import com.campusmart.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.BigDecimal;
@Configuration public class DataSeeder{@Bean CommandLineRunner seed(UserRepository users,CategoryRepository cats,ProductRepository products,PasswordEncoder enc){return args->{User admin=users.findByEmail("admin@campusmart.local").orElseGet(()->{User u=new User();u.setFullName("CampusMart Admin");u.setEmail("admin@campusmart.local");u.setPassword(enc.encode("Admin@123"));u.setCollegeName("CampusMart");u.setStudentId("ADMIN-001");u.setRole(User.Role.ADMIN);u.setVerified(true);return users.save(u);});User student=users.findByEmail("student@campus.local").orElseGet(()->{User u=new User();u.setFullName("Demo Student");u.setEmail("student@campus.local");u.setPassword(enc.encode("Student@123"));u.setCollegeName("Demo Engineering College");u.setStudentId("STU-001");u.setRole(User.Role.STUDENT);u.setVerified(true);return users.save(u);});String[] names={"Books","Calculators","Electronics","Lab Equipment","Engineering Tools","Stationery","Furniture","Accessories","College Essentials","Other"};for(String n:names)cats.findByNameIgnoreCase(n).orElseGet(()->cats.save(new Category(n)));if(products.count()==0){var calc=cats.findByNameIgnoreCase("Calculators").get();var books=cats.findByNameIgnoreCase("Books").get();var tools=cats.findByNameIgnoreCase("Engineering Tools").get();Product p=new Product();p.setName("Casio FX-991ES Plus");p.setDescription("Scientific calculator suitable for engineering students.");p.setCategory(calc);p.setPrice(new BigDecimal("450"));p.setCondition(Product.Condition.GOOD);p.setProductType(Product.ProductType.SELL);p.setLocation("Campus Block A");p.setSeller(student);products.save(p);Product b=new Product();b.setName("Engineering Mathematics Book");b.setDescription("Clean used reference book for semester preparation.");b.setCategory(books);b.setPrice(new BigDecimal("220"));b.setCondition(Product.Condition.GOOD);b.setProductType(Product.ProductType.SELL);b.setLocation("Library Gate");b.setSeller(student);products.save(b);Product t=new Product();t.setName("Engineering Drawing Kit");t.setDescription("Complete drawing kit for first-year engineering.");t.setCategory(tools);t.setPrice(new BigDecimal("300"));t.setCondition(Product.Condition.LIKE_NEW);t.setProductType(Product.ProductType.SELL);t.setLocation("Hostel Office");t.setSeller(student);products.save(t);}};}}
